def validate_term(node, K, fbn, quantified, counter):
    """Return (type, depth). Enforces grammar, ranges and node budget."""
    if not isinstance(node, dict):
        die("E_SCHEMA")
    keys = set(node.keys())
    if keys == {"field", "at"}:
        fname = node["field"]
        at = node["at"]
        fld = fbn.get(fname) if is_str(fname) else None
        if fld is None:
            die("E_SCHEMA")
        if is_int(at):
            if not (0 <= at < K):
                die("E_SCHEMA")
        elif is_str(at) and at == "$":
            if not quantified:
                die("E_SCHEMA")
        else:
            die("E_SCHEMA")
        counter[0] += 1
        if counter[0] > 64:
            die("E_SCHEMA")
        return fld["type"], 1
    if keys == {"const", "type"}:
        ctype = node["type"]
        cval = node["const"]
        if not is_str(ctype) or ctype not in ALL_TYPES:
            die("E_SCHEMA")
        if ctype in NUMERIC_TYPES:
            if not is_i32(cval):
                die("E_SCHEMA")
        elif ctype == "ID":
            if not is_str(cval) or RE_IDVAL.fullmatch(cval) is None:
                die("E_SCHEMA")
        else:
            if not is_bool(cval):
                die("E_SCHEMA")
        counter[0] += 1
        if counter[0] > 64:
            die("E_SCHEMA")
        return ctype, 1
    if keys == {"scale", "term"}:
        factor = node["scale"]
        if not (is_int(factor) and -1024 <= factor <= 1024):
            die("E_SCHEMA")
        ctype, cdepth = validate_term(node["term"], K, fbn, quantified, counter)
        if ctype not in NUMERIC_TYPES:
            die("E_SCHEMA")
        counter[0] += 1
        if counter[0] > 64:
            die("E_SCHEMA")
        return ctype, cdepth + 1
    if keys == {"add"}:
        parts = node["add"]
        if not isinstance(parts, list) or len(parts) != 2:
            die("E_SCHEMA")
        t1, d1 = validate_term(parts[0], K, fbn, quantified, counter)
        t2, d2 = validate_term(parts[1], K, fbn, quantified, counter)
        if t1 not in NUMERIC_TYPES or t1 != t2:
            die("E_SCHEMA")
        counter[0] += 1
        if counter[0] > 64:
            die("E_SCHEMA")
        return t1, (d1 if d1 > d2 else d2) + 1
    if keys == {"aggregate", "field", "from", "to"}:
        op = node["aggregate"]
        fname = node["field"]
        lo = node["from"]
        hi = node["to"]
        if not is_str(op) or op not in AGG_OPS:
            die("E_SCHEMA")
        fld = fbn.get(fname) if is_str(fname) else None
        if fld is None or fld["type"] not in NUMERIC_TYPES:
            die("E_SCHEMA")
        if not (is_int(lo) and is_int(hi)):
            die("E_SCHEMA")
        if not (0 <= lo <= hi < K):
            die("E_SCHEMA")
        counter[0] += 1
        if counter[0] > 64:
            die("E_SCHEMA")
        return fld["type"], 1
    die("E_SCHEMA")


def validate_cmp(node, K, fbn, quantified, counter):
    if not isinstance(node, dict):
        die("E_SCHEMA")
    if set(node.keys()) != {"cmp", "left", "right"}:
        die("E_SCHEMA")
    op = node["cmp"]
    if not is_str(op) or op not in CMP_OPS:
        die("E_SCHEMA")
    tleft, dleft = validate_term(node["left"], K, fbn, quantified, counter)
    tright, dright = validate_term(node["right"], K, fbn, quantified, counter)
    if dleft > 4 or dright > 4:
        die("E_SCHEMA")
    if tleft != tright:
        die("E_SCHEMA")
    if tleft not in NUMERIC_TYPES and op not in EQ_OPS:
        die("E_SCHEMA")
    return tleft


def validate_atom(atom, K, fbn):
    if not isinstance(atom, dict):
        die("E_SCHEMA")
    keys = set(atom.keys())
    if keys == {"cmp", "left", "right"}:
        validate_cmp(atom, K, fbn, False, [0])
    elif keys == {"quantifier", "from", "to", "predicate"}:
        quant = atom["quantifier"]
        if not is_str(quant) or quant not in ("any", "all"):
            die("E_SCHEMA")
        lo = atom["from"]
        hi = atom["to"]
        if not (is_int(lo) and is_int(hi)):
            die("E_SCHEMA")
        if not (0 <= lo <= hi < K):
            die("E_SCHEMA")
        validate_cmp(atom["predicate"], K, fbn, True, [0])
    else:
        die("E_SCHEMA")


